window.AUTH=window.AUTH||{};window.AUTH["19-1434"]={"d":"19-1434","id":"2020/19-1434","n":"United States v. Arthrex, Inc.","briefs":[{"k":"respondent","label":"Brief of respondent Arthrex, Inc.","date":"2020-12-23","url":"https://www.supremecourt.gov/DocketPDF/19/19-1434/164642/20201223142232136_Arthrex%20merits%20brief%20-%20efile.pdf","side":"res","n":121}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/594us1r50_m6io.pdf","tr":true,"items":[{"t":"case","label":"Abrams v. Soc. Sec. Admin.","cite":"703 F.3d 538","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/703/538/","by":{"0":"37"}},{"t":"case","label":"Alaska Airlines, Inc. v. Brock","cite":"480 U.S. 678","y":1987,"id":"1986/85-920","sc":1,"sum":"Section 43(f)(3)'s legislative-veto provision is severable from the remainder of the EPP program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 54"}},{"t":"case","label":"Ass’n of Am. R.Rs. v. U.S. Dep’t of Transp.","cite":"821 F.3d 19","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/821/19/","by":{"0":"21"}},{"t":"case","label":"Ayotte v. Planned Parenthood of N. New Eng.","cite":"546 U.S. 320","y":2006,"id":"2005/04-1144","sc":1,"op":1,"sum":"In a rare unanimous decision regarding abortion, the Supreme Court sidestepped the most contentious questions of the case and focused instead on the proper remedy when a portion of a statute is found unconstitutional.","sumSrc":"Oyez","by":{"0":"59, 63"}},{"t":"case","label":"Barr v. Am. Ass’n of Pol. Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"op":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"0":"45, 57"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"op":2,"ar":1,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"0":"38, 47, 57"}},{"t":"case","label":"Brown v. Dep’t of Navy","cite":"229 F.3d 1356","y":2000,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/229/1356/","by":{"0":"6, 11, 36"}},{"t":"case","label":"Butz v. Economou","cite":"438 U.S. 478","y":1978,"id":"1977/76-709","sc":1,"sum":"Federal officials who perform adjudicatory, or other similar prosecutorial functions, cannot, however, be held liable for mere \"good faith\" judgment errors. The Court reasoned that the risk of making unconstitutional determinations is outweighed by the need to preserve independent judgement, through grants of absolute immunity to judges and other similarly situated decision makers.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Clarian Health W., LLC v. Hargan","cite":"878 F.3d 346","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/878/346/","by":{"0":"43"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"62"}},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"op":22,"sum":"The Court found that the President did not have immunity from civil litigation.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Collins v. Miller","cite":"252 U.S. 364","y":1920,"id":"scdb/1919-114","sc":1,"by":{"0":"27"}},{"t":"case","label":"Cooper Techs. Co. v. Dudas","cite":"536 F.3d 1330","y":2008,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/536/1330/","by":{"0":"43"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"op":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Dep’t of Transp. v. Ass’n of Am. R.Rs.","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"sum":"The Court held that for purposes of the validity of metrics and standards, Amtrak is a governmental entity.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Edmond v. United States","cite":"520 U.S. 651","y":1997,"id":"1996/96-262","sc":1,"op":47,"ar":21,"sum":"The Court held that the judicial appointments were valid. The Court unanimously found that Congress has authorized the Secretary to appoint civilian members of the Coast Guard Court of Criminal Appeals.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Fla. Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"62"}},{"t":"case","label":"Facebook, Inc. v. Windy City Innovations, LLC","cite":"973 F.3d 1321","y":2020,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/973/1321/","by":{"0":"40, 43"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Acct. Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":10,"ar":3,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Freytag v. Comm’r","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"op":4,"ar":1,"sum":"On the question of whether 7443A permitted the assignment of complex cases to special trial judges, the Supreme Court unanimously ruled that the statute unambiguously did allow such appointments. Justice Harry Blackmun, in the majority opinion, wrote, \"The plain language of 7443A(b)(4) surely authorizes the Chief Judge's assignment of petitioners' cases to a special trial judge.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Humphrey’s Ex’r v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"op":1,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Intercollegiate Broad. Sys., Inc. v. Copyright Royalty Bd.","cite":"684 F.3d 1332","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/684/1332/","by":{"0":"30"}},{"t":"case","label":"King v. Frazier","cite":"77 F.3d 1361","y":1996,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/77/1361/","by":{"0":"37"}},{"t":"case","label":"Kuretski v. Comm’r","cite":"755 F.3d 929","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/755/929/","by":{"0":"31, 34"}},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"op":6,"sum":"The Court decided that administrative law judges of the Securities and Exchange Commission are \"officers of the United States\" subject to the Constitution's Appointments Clause.","sumSrc":"Oyez","by":{"0":"12, 25, 26, 51"}},{"t":"case","label":"Medtronic, Inc. v. Mirowski Fam. Ventures, LLC","cite":"571 U.S. 191","y":2014,"id":"2013/12-1128","sc":1,"sum":"The Court held that, in a patent infringement case, the burden of proof of infringement is on the patent holder.","sumSrc":"Oyez","by":{"0":"59"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"op":6,"ar":6,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"0":"27, 39"}},{"t":"case","label":"Murphy v. Nat’l Collegiate Athletic Ass’n","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"0":"47, 54"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"op":2,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"N. Pipeline Constr. Co. v. Marathon Pipe Line Co.","cite":"458 U.S. 50","y":1982,"id":"1981/81-150","sc":1,"sum":"A plurality held that Congress had essentially conferred Article III powers to an adjunct system of courts and, consequently, \"impermissibly removed most, if not all, of the essential attributes of the judicial power\" from the district courts.","sumSrc":"Oyez","by":{"0":"59"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"0":"35, 45"}},{"t":"case","label":"Nguyen v. Dep’t of Homeland Sec.","cite":"737 F.3d 711","y":2013,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/737/711/","by":{"0":"37"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Ramspeck v. Fed. Trial Exam’rs Conf.","cite":"345 U.S. 128","y":1953,"id":"scdb/1952-062","sc":1,"sum":"Certain -provisions of regulations promulgated by the Civil Service Commission under § 11 of the Administrative Procedure Act and governing the classification, promotion, compensation fnd tenure of trial examiners and the assignment of cases to them are here sustained as conforming to the statute and carrying out the purpose and intent of Congress.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 50"}},{"t":"case","label":"Randall v. Sorrell","cite":"548 U.S. 230","y":2006,"id":"2005/04-1528","sc":1,"sum":"The opinion by Justice Stephen Breyer held that the Court should let stand the Buckley decision and its invalidation of expenditure limits. Vermont's argument that such limits prevent candidates from spending too much time fund-raising was deemed irrelevant because it was \"perfectly obvious\" and would not have changed the result in Buckley .","sumSrc":"Oyez","by":{"0":"56"}},{"t":"case","label":"Ryder Truck Lines, Inc. v. United States","cite":"716 F.2d 1369","y":1983,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/716/1369/","op":1,"by":{"0":"43"}},{"t":"case","label":"SAS Inst. Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"0":"7, 53"}},{"t":"case","label":"Seila Law LLC v. Consumer Fin. Prot. Bureau","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"op":8,"ar":3,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Shoaf v. Dep’t of Agric.","cite":"260 F.3d 1336","y":2001,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/260/1336/","by":{"0":"38"}},{"t":"case","label":"Tokyo Kikai Seisakusho, Ltd. v. United States","cite":"529 F.3d 1352","y":2008,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/529/1352/","by":{"0":"41"}},{"t":"case","label":"United States v. Allred","cite":"155 U.S. 591","y":1895,"id":"scdb/1894-064","sc":1,"op":1,"sum":"A commissioner of a Circuit Court is an officer of the court, authorized by law, and is entitled to his fees in the following cases when certified by the court as correct:","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"45, 47, 54, 63"}},{"t":"case","label":"United States v. Giordano","cite":"416 U.S. 505","y":1974,"id":"1973/72-1057","sc":1,"sum":"The Court held that evidence obtained from improperly authorized wiretap applications, along with any evidence obtained from extensions of those applications, must be suppressed.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"United States v. Nat’l Treasury Emps. Union","cite":"513 U.S. 454","y":1995,"id":"1994/93-1170","sc":1,"op":1,"sum":"In a 6 to 3 decision delivered by Justice John Paul Stevens, the Court declared that a flat ban violated free-speech rights. Concerns about impropriety do not apply if there is no link between a government employee's job and \"the subject matter of the expression or the character of the payor.\".","sumSrc":"Oyez","by":{"0":"59, 63"}},{"t":"case","label":"United States ex rel. Accardi v. Shaughnessy","cite":"347 U.S. 260","y":1954,"id":"1940-1955/347us260","sc":1,"sum":"Petitioner is entitled to an opportunity in thp district court to prove the allegation; and, if he does prove it, he should receive a new hearing before the Board without the burden of previous proscription by the list.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Utica Packing Co. v. Block","cite":"781 F.2d 71","y":1986,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/781/71/","by":{"0":"41"}},{"t":"case","label":"Ward v. Village of Monroeville","cite":"409 U.S. 57","y":1972,"id":"1972/71-496","sc":1,"sum":"Petitioner was denied a trial before a disinterested and impartial judicial officer as guaranteed by the Due Process Clause of the Fourteenth Amendment where he was compelled to stand trial for traffic offenses before the mayor, who was responsible for village finances and whose court through fines, forfeitures, costs, and fees provided a substantial portion of village funds. Tumey v. Ohio, 273 U. S. 510. A …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"63"}},{"t":"case","label":"Wiener v. United States","cite":"357 U.S. 349","y":1958,"id":"1957/52","sc":1,"op":3,"sum":"The Court held that the President did not have the authority to remove individuals from the War Claims Commission at will.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Wong Yang Sung v. McGrath","cite":"339 U.S. 33","y":1950,"id":"scdb/1949-048","sc":1,"sum":"This was contrary to the purpose of the Administrative Procedure Act to ameliorate the evils resulting from a combination of the prosecuting and adjudicating functions in administrative proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"18"}},{"t":"const","label":"Article II, Section 1","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"]],"by":{"0":"18"}},{"t":"const","label":"Article II, Section 2","clauses":[["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"The President shall be Commander in Chief of the Army and Navy of the United States, and of the Militia of the several States, when called into the actual Service of the United States; he may require the Opinion, in writing, of the principal Officer in each of the executive Departments, upon any Subject relating to the Duties of their respective Offices, and he shall have Power to grant Reprieves and Pardons for Offences against the United States, except in Cases of Impeachment. He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments. The President shall have Power to fill up all Vacancies that may happen during the Recess of the Senate, by granting Commissions which shall expire at the End of their next Session.","by":{"0":"passim"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"23, 31, 48, 54"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"0":"48"}},{"t":"usc","label":"35 U.S.C. § 3","url":"https://www.law.cornell.edu/uscode/text/35/3","subs":["(a)","(a)(1)","(a)(2)(A)","(b)","(b)(2)(C)","(b)(6)","(c)"],"stext":{"head":"§3. Officers and employees","paras":[[0,"(a) Under Secretary and Director.—"],[1,"(1) In general.—The powers and duties of the United States Patent and Trademark Office shall be vested in an Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office (in this title referred to as the \"Director\"), who shall be a citizen of the United States and who shall be appointed by the President, by and with the advice and consent of the Senate. The Director shall be a person who has a professional background and experience in patent or trademark law."],[1,"(2) Duties.—"],[2,"(A) In general.—The Director shall be responsible for providing policy direction and management supervision for the Office and for the issuance of patents and the registration of trademarks. The Director shall perform these duties in a fair, impartial, and equitable manner."],[2,"(B) Consulting with the public advisory committees.—The Director shall consult with the Patent Public Advisory Committee established in section 5 on a regular basis on matters relating to the patent operations of the Office, shall consult with the Trademark Public Advisory Committee established in section 5 on a regular basis on matters relating to the trademark operations of the Office, and shall consult with the respective Public Advisory Committee before submitting budgetary proposals to the Office of Management and Budget or changing or proposing to change patent or trademark user fees or patent or trademark regulations which are subject to the requirement to provide notice and opportunity for public comment under section 553 of title 5, as the case may be."],[1,"(3) Oath.—The Director shall, before taking office, take an oath to discharge faithfully the duties of the Office."],[1,"(4) Removal.—The Director may be removed from office by the President. The President shall provide notification of any such removal to both Houses of Congress."],[0,"(b) Officers and Employees of the Office.—"],[1,"(1) Deputy under secretary and deputy director.—The Secretary of Commerce, upon nomination by the Director, shall appoint a Deputy Under Secretary of Commerce for Intellectual Property and Deputy Director of the United States Patent and Trademark Office who shall be vested with the authority to act in the capacity of the Director in the event of the absence or incapacity of the Director. The Deputy Director shall be a citizen of the United States who has a professional background and experience in patent or trademark law."],[1,"(2) Commissioners.—"],[2,"(A) Appointment and duties.—The Secretary of Commerce shall appoint a Commissioner for Patents and a Commissioner for Trademarks, without regard to chapter 33, 51, or 53 of title 5. The Commissioner for Patents shall be a citizen of the United States with demonstrated management ability and professional background and experience in patent law and serve for a term of 5 years. The Commissioner for Trademarks shall be a citizen of the United States with demonstrated management ability and professional background and experience in trademark law and serve for a term of 5 years. The Commissioner for Patents and the Commissioner for Trademarks shall serve as the chief operating officers for the operations of the Office relating to patents and trademarks, respectively, and shall be responsible for the management and direction of all aspects of the activities of the Office that affect the administration of patent and trademark operations, respectively. The Secretary may reappoint a Commissioner to subsequent terms of 5 years as long as the performance of the Commissioner as set forth in the performance agreement in subparagraph (B) is satisfactory."],[2,"(B) Salary and performance agreement.—The Commissioners shall be paid an annual rate of basic pay not to exceed the maximum rate of basic pay for the Senior Executive Service established under section 5382 of title 5, including any applicable locality-based comparability payment that may be authorized under section 5304(h)(2)(C) of title 5. The compensation of the Commissioners shall be considered, for purposes of section 207(c)(2)(A) of title 18, to be the equivalent of that described under clause (ii) of section 207(c)(2)(A) of title 18. In addition, the Commissioners may receive a bonus in an amount of up to, but not in excess of, 50 percent of the Commissioners' annual rate of basic pay, based upon an evaluation by the Secretary of Commerce, acting through the Director, of the Commissioners' performance as defined in an annual performance agreement between the Commissioners and the Secretary. The annual performance agreements shall incorporate measurable organization and individual goals in key operational areas as delineated in an annual performance plan agreed to by the Commissioners and the Secretary. Payment of a bonus under this subparagraph may be made to the Commissioners only to the extent that such payment does not cause the Commissioners' total aggregate compensation in a calendar year to equal or exceed the amount of the salary of the Vice President under section 104 of title 3."],[2,"(C) Removal.—The Commissioners may be removed from office by the Secretary for misconduct or nonsatisfactory performance under the performance agreement described in subparagraph (B), without regard to the provisions of title 5. The Secretary shall provide notification of any such removal to both Houses of Congress."],[1,"(3) Other officers and employees.—The Director shall—"],[2,"(A) appoint such officers, employees (including attorneys), and agents of the Office as the Director considers necessary to carry out the functions of the Office; and"],[2,"(B) define the title, authority, and duties of such officers and employees and delegate to them such of the powers vested in the Office as the Director may determine."],[1,"The Office shall not be subject to any administratively or statutorily imposed limitation on positions or personnel, and no positions or personnel of the Office shall be taken into account for purposes of applying any such limitation."],[1,"(4) Training of examiners.—The Office shall submit to the Congress a proposal to provide an incentive program to retain as employees patent and trademark examiners of the primary examiner grade or higher who are eligible for retirement, for the sole purpose of training patent and trademark examiners."],[1,"(5) National security positions.—The Director, in consultation with the Director of the Office of Personnel Management, shall maintain a program for identifying national security positions and providing for appropriate security clearances, in order to maintain the secrecy of certain inventions, as described in section 181, and to prevent disclosure of sensitive and strategic information in the interest of national security."],[1,"(6) Administrative patent judges and administrative trademark judges.—The Director may fix the rate of basic pay for the administrative patent judges appointed pursuant to section 6 and the administrative trademark judges appointed pursuant to section 17 of the Trademark Act of 1946 (15 U.S.C. 1067) at not greater than the rate of basic pay payable for level III of the Executive Schedule under section 5314 of title 5. The payment of a rate of basic pay under this paragraph shall not be subject to the pay limitation under section 5306(e) or 5373 of title 5."],[0,"(c) Continued Applicability of Title 5.—Officers and employees of the Office shall be subject to the provisions of title 5, relating to Federal employees."],[0,"(d) Adoption of Existing Labor Agreements.—The Office shall adopt all labor agreements which are in effect, as of the day before the effective date of the Patent and Trademark Office Efficiency Act, with respect to such Office (as then in effect)."],[0,"(e) Carryover of Personnel.—"],[1,"(1) From pto.—Effective as of the effective date of the Patent and Trademark Office Efficiency Act, all officers and employees of the Patent and Trademark Office on the day before such effective date shall become officers and employees of the Office, without a break in service."],[1,"(2) Other personnel.—Any individual who, on the day before the effective date of the Patent and Trademark Office Efficiency Act, is an officer or employee of the Department of Commerce (other than an officer or employee under paragraph (1)) shall be transferred to the Office, as necessary to carry out the purposes of that Act, if—"],[2,"(A) such individual serves in a position for which a major function is the performance of work reimbursed by the Patent and Trademark Office, as determined by the Secretary of Commerce;"],[2,"(B) such individual serves in a position that performed work in support of the Patent and Trademark Office during at least half of the incumbent's work time, as determined by the Secretary of Commerce; or"],[2,"(C) such transfer would be in the interest of the Office, as determined by the Secretary of Commerce in consultation with the Director."],[0,"Any transfer under this paragraph shall be effective as of the same effective date as referred to in paragraph (1), and shall be made without a break in service."],[0,"(f) Transition Provisions.—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/3?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§3. Officers and employees","tname":"Patents","by":{"0":"7, 23, 40, 43, 7, 37, 38, 6, 36"}},{"t":"usc","label":"35 U.S.C. § 6","url":"https://www.law.cornell.edu/uscode/text/35/6","subs":["(a)","(b)","(b)(1)","(b)(2)","(b)(3)","(c)"],"stext":{"head":"§6. Patent Trial and Appeal Board","paras":[[0,"(a) In General.—There shall be in the Office a Patent Trial and Appeal Board. The Director, the Deputy Director, the Commissioner for Patents, the Commissioner for Trademarks, and the administrative patent judges shall constitute the Patent Trial and Appeal Board. The administrative patent judges shall be persons of competent legal knowledge and scientific ability who are appointed by the Secretary, in consultation with the Director. Any reference in any Federal law, Executive order, rule, regulation, or delegation of authority, or any document of or pertaining to the Board of Patent Appeals and Interferences is deemed to refer to the Patent Trial and Appeal Board."],[0,"(b) Duties.—The Patent Trial and Appeal Board shall—"],[1,"(1) on written appeal of an applicant, review adverse decisions of examiners upon applications for patents pursuant to section 134(a);"],[1,"(2) review appeals of reexaminations pursuant to section 134(b);"],[1,"(3) conduct derivation proceedings pursuant to section 135; and"],[1,"(4) conduct inter partes reviews and post-grant reviews pursuant to chapters 31 and 32."],[0,"(c) 3-Member Panels.—Each appeal, derivation proceeding, post-grant review, and inter partes review shall be heard by at least 3 members of the Patent Trial and Appeal Board, who shall be designated by the Director. Only the Patent Trial and Appeal Board may grant rehearings."],[0,"(d) Treatment of Prior Appointments.—The Secretary of Commerce may, in the Secretary's discretion, deem the appointment of an administrative patent judge who, before the date of the enactment of this subsection, held office pursuant to an appointment by the Director to take effect on the date on which the Director initially appointed the administrative patent judge. It shall be a defense to a challenge to the appointment of an administrative patent judge on the basis of the judge's having been originally appointed by the Director that the administrative patent judge so appointed was acting as a de facto officer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/6?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§6. Patent Trial and Appeal Board","tname":"Patents","by":{"0":"passim, 7, 33, 40, 7, 7, 7, 7, 23, 41, 54"}},{"t":"usc","label":"35 U.S.C. § 134","url":"https://www.law.cornell.edu/uscode/text/35/134","by":{"0":"5"}},{"t":"usc","label":"35 U.S.C. § 135","url":"https://www.law.cornell.edu/uscode/text/35/135","by":{"0":"7"}},{"t":"usc","label":"35 U.S.C. § 141","url":"https://www.law.cornell.edu/uscode/text/35/141","by":{"0":"7, 54"}},{"t":"usc","label":"35 U.S.C. § 305","url":"https://www.law.cornell.edu/uscode/text/35/305","by":{"0":"6"}},{"t":"usc","label":"35 U.S.C. § 311","url":"https://www.law.cornell.edu/uscode/text/35/311","stext":{"head":"§311. Inter partes review","paras":[[0,"(a) In General.—Subject to the provisions of this chapter, a person who is not the owner of a patent may file with the Office a petition to institute an inter partes review of the patent. The Director shall establish, by regulation, fees to be paid by the person requesting the review, in such amounts as the Director determines to be reasonable, considering the aggregate costs of the review."],[0,"(b) Scope.—A petitioner in an inter partes review may request to cancel as unpatentable 1 or more claims of a patent only on a ground that could be raised under section 102 or 103 and only on the basis of prior art consisting of patents or printed publications."],[0,"(c) Filing Deadline.—A petition for inter partes review shall be filed after the later of either—"],[1,"(1) the date that is 9 months after the grant of a patent; or"],[1,"(2) if a post-grant review is instituted under chapter 32, the date of the termination of such post-grant review."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/311?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§311. Inter partes review","tname":"Patents","by":{"0":"7"}},{"t":"usc","label":"35 U.S.C. § 314","url":"https://www.law.cornell.edu/uscode/text/35/314","subs":["(a)","(a)(2006)"],"stext":{"head":"§314. Institution of inter partes review","paras":[[0,"(a) Threshold.—The Director may not authorize an inter partes review to be instituted unless the Director determines that the information presented in the petition filed under section 311 and any response filed under section 313 shows that there is a reasonable likelihood that the petitioner would prevail with respect to at least 1 of the claims challenged in the petition."],[0,"(b) Timing.—The Director shall determine whether to institute an inter partes review under this chapter pursuant to a petition filed under section 311 within 3 months after—"],[1,"(1) receiving a preliminary response to the petition under section 313; or"],[1,"(2) if no such preliminary response is filed, the last date on which such response may be filed."],[0,"(c) Notice.—The Director shall notify the petitioner and patent owner, in writing, of the Director's determination under subsection (a), and shall make such notice available to the public as soon as is practicable. Such notice shall include the date on which the review shall commence."],[0,"(d) No Appeal.—The determination by the Director whether to institute an inter partes review under this section shall be final and nonappealable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/314?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§314. Institution of inter partes review","tname":"Patents","by":{"0":"7, 6"}},{"t":"usc","label":"35 U.S.C. § 316","url":"https://www.law.cornell.edu/uscode/text/35/316","subs":["(a)"],"by":{"0":"7, 43, 53"}},{"t":"usc","label":"35 U.S.C. § 318","url":"https://www.law.cornell.edu/uscode/text/35/318","subs":["(a)","(b)"],"stext":{"head":"§318. Decision of the Board","paras":[[0,"(a) Final Written Decision.—If an inter partes review is instituted and not dismissed under this chapter, the Patent Trial and Appeal Board shall issue a final written decision with respect to the patentability of any patent claim challenged by the petitioner and any new claim added under section 316(d)."],[0,"(b) Certificate.—If the Patent Trial and Appeal Board issues a final written decision under subsection (a) and the time for appeal has expired or any appeal has terminated, the Director shall issue and publish a certificate canceling any claim of the patent finally determined to be unpatentable, confirming any claim of the patent determined to be patentable, and incorporating in the patent by operation of the certificate any new or amended claim determined to be patentable."],[0,"(c) Intervening Rights.—Any proposed amended or new claim determined to be patentable and incorporated into a patent following an inter partes review under this chapter shall have the same effect as that specified in section 252 for reissued patents on the right of any person who made, purchased, or used within the United States, or imported into the United States, anything patented by such proposed amended or new claim, or who made substantial preparation therefor, before the issuance of a certificate under subsection (b)."],[0,"(d) Data on Length of Review.—The Office shall make available to the public data describing the length of time between the institution of, and the issuance of a final written decision under subsection (a) for, each inter partes review."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/318?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§318. Decision of the Board","tname":"Patents","by":{"0":"7, 23"}},{"t":"usc","label":"35 U.S.C. § 319","url":"https://www.law.cornell.edu/uscode/text/35/319","stext":{"head":"§319. Appeal","paras":[[0,"A party dissatisfied with the final written decision of the Patent Trial and Appeal Board under section 318(a) may appeal the decision pursuant to sections 141 through 144. Any party to the inter partes review shall have the right to be a party to the appeal."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/319?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§319. Appeal","tname":"Patents","by":{"0":"7, 23"}},{"t":"usc","label":"2 U.S.C. § 136-1","url":"https://www.law.cornell.edu/uscode/text/2/136-1","subs":["(a)"],"by":{"0":"31"}},{"t":"usc","label":"5 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/5/557","subs":["(b)"],"stext":{"head":"§557. Initial decisions; conclusiveness; review by agency; submissions by parties; contents of decisions; record","paras":[[0,"(a) This section applies, according to the provisions thereof, when a hearing is required to be conducted in accordance with section 556 of this title."],[0,"(b) When the agency did not preside at the reception of the evidence, the presiding employee or, in cases not subject to section 554(d) of this title, an employee qualified to preside at hearings pursuant to section 556 of this title, shall initially decide the case unless the agency requires, either in specific cases or by general rule, the entire record to be certified to it for decision. When the presiding employee makes an initial decision, that decision then becomes the decision of the agency without further proceedings unless there is an appeal to, or review on motion of, the agency within time provided by rule. On appeal from or review of the initial decision, the agency has all the powers which it would have in making the initial decision except as it may limit the issues on notice or by rule. When the agency makes the decision without having presided at the reception of the evidence, the presiding employee or an employee qualified to preside at hearings pursuant to section 556 of this title shall first recommend a decision, except that in rule making or determining applications for initial licenses—"],[1,"(1) instead thereof the agency may issue a tentative decision or one of its responsible employees may recommend a decision; or"],[1,"(2) this procedure may be omitted in a case in which the agency finds on the record that due and timely execution of its functions imperatively and unavoidably so requires."],[0,"(c) Before a recommended, initial, or tentative decision, or a decision on agency review of the decision of subordinate employees, the parties are entitled to a reasonable opportunity to submit for the consideration of the employees participating in the decisions—"],[1,"(1) proposed findings and conclusions; or"],[1,"(2) exceptions to the decisions or recommended decisions of subordinate employees or to tentative agency decisions; and"],[1,"(3) supporting reasons for the exceptions or proposed findings or conclusions."],[0,"The record shall show the ruling on each finding, conclusion, or exception presented. All decisions, including initial, recommended, and tentative decisions, are a part of the record and shall include a statement of—"],[1,"(A) findings and conclusions, and the reasons or basis therefor, on all the material issues of fact, law, or discretion presented on the record; and"],[1,"(B) the appropriate rule, order, sanction, relief, or denial thereof."],[0,"(d)(1) In any agency proceeding which is subject to subsection (a) of this section, except to the extent required for the disposition of ex parte matters as authorized by law—"],[1,"(A) no interested person outside the agency shall make or knowingly cause to be made to any member of the body comprising the agency, administrative law judge, or other employee who is or may reasonably be expected to be involved in the decisional process of the proceeding, an ex parte communication relevant to the merits of the proceeding;"],[1,"(B) no member of the body comprising the agency, administrative law judge, or other employee who is or may reasonably be expected to be involved in the decisional process of the proceeding, shall make or knowingly cause to be made to any interested person outside the agency an ex parte communication relevant to the merits of the proceeding;"],[1,"(C) a member of the body comprising the agency, administrative law judge, or other employee who is or may reasonably be expected to be involved in the decisional process of such proceeding who receives, or who makes or knowingly causes to be made, a communication prohibited by this subsection shall place on the public record of the proceeding:"],[2,"(i) all such written communications;"],[2,"(ii) memoranda stating the substance of all such oral communications; and"],[2,"(iii) all written responses, and memoranda stating the substance of all oral responses, to the materials described in clauses (i) and (ii) of this subparagraph;"],[1,"(D) upon receipt of a communication knowingly made or knowingly caused to be made by a party in violation of this subsection, the agency, administrative law judge, or other employee presiding at the hearing may, to the extent consistent with the interests of justice and the policy of the underlying statutes, require the party to show cause why his claim or interest in the proceeding should not be dismissed, denied, disregarded, or otherwise adversely affected on account of such violation; and"],[1,"(E) the prohibitions of this subsection shall apply beginning at such time as the agency may designate, but in no case shall they begin to apply later than the time at which a proceeding is noticed for hearing unless the person responsible for the communication has knowledge that it will be noticed, in which case the prohibitions shall apply beginning at the time of his acquisition of such knowledge."],[0,"(2) This subsection does not constitute authority to withhold information from Congress."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/557?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§557. Initial decisions; conclusiveness; review by agency; submissions by parties; contents of decisions; record","tname":"Government Organization and Employees","by":{"0":"30"}},{"t":"usc","label":"5 U.S.C. § 7512","url":"https://www.law.cornell.edu/uscode/text/5/7512","subs":["(4)"],"by":{"0":"38"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(a)","(b)","(c)","(d)"],"stext":{"head":"§7513. Cause and procedure","paras":[[0,"(a) Under regulations prescribed by the Office of Personnel Management, an agency may take an action covered by this subchapter against an employee only for such cause as will promote the efficiency of the service."],[0,"(b) An employee against whom an action is proposed is entitled to—"],[1,"(1) at least 30 days' advance written notice, unless there is reasonable cause to believe the employee has committed a crime for which a sentence of imprisonment may be imposed, stating the specific reasons for the proposed action;"],[1,"(2) a reasonable time, but not less than 7 days, to answer orally and in writing and to furnish affidavits and other documentary evidence in support of the answer;"],[1,"(3) be represented by an attorney or other representative; and"],[1,"(4) a written decision and the specific reasons therefor at the earliest practicable date."],[0,"(c) An agency may provide, by regulation, for a hearing which may be in lieu of or in addition to the opportunity to answer provided under subsection (b)(2) of this section."],[0,"(d) An employee against whom an action is taken under this section is entitled to appeal to the Merit Systems Protection Board under section 7701 of this title."],[0,"(e) Copies of the notice of proposed action, the answer of the employee when written, a summary thereof when made orally, the notice of decision and reasons therefor, and any order effecting an action covered by this subchapter, together with any supporting material, shall be maintained by the agency and shall be furnished to the Board upon its request and to the employee affected upon the employee's request."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7513?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§7513. Cause and procedure","tname":"Government Organization and Employees","by":{"0":"4, passim, 6, 37, 6, 37, 6, 37"}},{"t":"usc","label":"5 U.S.C. § 7521","url":"https://www.law.cornell.edu/uscode/text/5/7521","subs":["(a)"],"by":{"0":"51"}},{"t":"usc","label":"5 U.S.C. § 7543","url":"https://www.law.cornell.edu/uscode/text/5/7543","subs":["(a)"],"stext":{"head":"§7543. Cause and procedure","paras":[[0,"(a) Under regulations prescribed by the Office of Personnel Management, an agency may take an action covered by this subchapter against an employee only for misconduct, neglect of duty, malfeasance, or failure to accept a directed reassignment or to accompany a position in a transfer of function."],[0,"(b) An employee against whom an action covered by this subchapter is proposed is entitled to—"],[1,"(1) at least 30 days' advance written notice, unless there is reasonable cause to believe that the employee has committed a crime for which a sentence of imprisonment can be imposed, stating specific reasons for the proposed action;"],[1,"(2) a reasonable time, but not less than 7 days, to answer orally and in writing and to furnish affidavits and other documentary evidence in support of the answer;"],[1,"(3) be represented by an attorney or other representative; and"],[1,"(4) a written decision and specific reasons therefor at the earliest practicable date."],[0,"(c) An agency may provide, by regulation, for a hearing which may be in lieu of or in addition to the opportunity to answer provided under subsection (b)(2) of this section."],[0,"(d) An employee against whom an action is taken under this section is entitled to appeal to the Merit Systems Protection Board under section 7701 of this title."],[0,"(e) Copies of the notice of proposed action, the answer of the employee when written, and a summary thereof when made orally, the notice of decision and reasons therefor, and any order effecting an action covered by this subchapter, together with any supporting material, shall be maintained by the agency and shall be furnished to the Merit Systems Protection Board upon its request and to the employee affected upon the employee's request."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7543?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7543. Cause and procedure","tname":"Government Organization and Employees","by":{"0":"37"}},{"t":"usc","label":"10 U.S.C. § 942","url":"https://www.law.cornell.edu/uscode/text/10/942","subs":["(b)(1)"],"by":{"0":"20"}},{"t":"usc","label":"12 U.S.C. § 5491","url":"https://www.law.cornell.edu/uscode/text/12/5491","subs":["(c)(3)"],"by":{"0":"36"}},{"t":"usc","label":"15 U.S.C. § 78d-1","url":"https://www.law.cornell.edu/uscode/text/15/78d-1","subs":["(c)"],"by":{"0":"26"}},{"t":"usc","label":"15 U.S.C. § 7217","url":"https://www.law.cornell.edu/uscode/text/15/7217","subs":["(c)"],"by":{"0":"21"}},{"t":"usc","label":"17 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/17/701","subs":["(a)"],"by":{"0":"31"}},{"t":"usc","label":"17 U.S.C. § 802","url":"https://www.law.cornell.edu/uscode/text/17/802","by":{"0":"30"}},{"t":"usc","label":"26 U.S.C. § 7443A","url":"https://www.law.cornell.edu/uscode/text/26/7443A","subs":["(c)"],"by":{"0":"26"}},{"t":"usc","label":"38 U.S.C. § 7251","url":"https://www.law.cornell.edu/uscode/text/38/7251","stext":{"head":"§7251. Status","paras":[[0,"There is hereby established, under Article I of the Constitution of the United States, a court of record to be known as the United States Court of Appeals for Veterans Claims."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7251?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7251. Status","tname":"Veterans' Benefits","by":{"0":"31"}},{"t":"usc","label":"38 U.S.C. § 7252","url":"https://www.law.cornell.edu/uscode/text/38/7252","subs":["(a)"],"by":{"0":"31"}},{"t":"usc","label":"38 U.S.C. § 7253","url":"https://www.law.cornell.edu/uscode/text/38/7253","subs":["(b)","(c)"],"by":{"0":"31, 31"}},{"t":"usc","label":"42 U.S.C. § 610","url":"https://www.law.cornell.edu/uscode/text/42/610","subs":["(c)"],"by":{"0":"32"}},{"t":"usc","label":"42 U.S.C. § 1316","url":"https://www.law.cornell.edu/uscode/text/42/1316","subs":["(e)(2)(B)"],"by":{"0":"32"}},{"t":"law","label":"Pub. L. No. 82-593","url":"https://www.govinfo.gov/link/statute/66/792","by":{"0":"4, 33, 45"}},{"t":"law","label":"Pub. L. No. 85-755","url":"https://www.govinfo.gov/link/statute/72/848","by":{"0":"34"}},{"t":"law","label":"Pub. L. No. 93-601","url":"https://www.govinfo.gov/link/statute/88/1956","by":{"0":"4, 33, 52"}},{"t":"law","label":"Pub. L. No. 96-517","url":"https://www.govinfo.gov/link/statute/94/3015","by":{"0":"5"}},{"t":"law","label":"Pub. L. No. 98-622","url":"https://www.govinfo.gov/link/statute/98/3383","by":{"0":"5"}},{"t":"law","label":"Pub. L. No. 99-514","url":"https://www.govinfo.gov/link/statute/100/2085","by":{"0":"25"}},{"t":"law","label":"Pub. L. No. 106-113","url":"https://www.govinfo.gov/link/plaw/106/public/113","by":{"0":"5, 33"}},{"t":"law","label":"Pub. L. No. 110-313","url":"https://www.govinfo.gov/link/plaw/110/public/313","by":{"0":"5"}},{"t":"law","label":"Leahy-Smith America Invents Act, Pub. L. No. 112-29","url":"https://www.govinfo.gov/link/plaw/112/public/29","by":{"0":"passim"}},{"t":"reg","label":"17 C.F.R. § 201.155","url":"https://www.ecfr.gov/current/title-17/section-201.155","subs":["(a)","(b)"],"by":{"0":"26, 26"}},{"t":"reg","label":"17 C.F.R. § 201.360","url":"https://www.ecfr.gov/current/title-17/section-201.360","subs":["(d)"],"by":{"0":"26"}},{"t":"reg","label":"37 C.F.R. § 42.4","url":"https://www.ecfr.gov/current/title-37/section-42.4","subs":["(a)"],"by":{"0":"7"}},{"t":"reg","label":"37 C.F.R. § 42.100","url":"https://www.ecfr.gov/current/title-37/section-42.100","subs":["(a)"],"by":{"0":"7, 53"}},{"t":"reg","label":"EXECUTIVE AND ADMINISTRATIVE MATERIALS, 38 Fed. Reg. 9906","url":"https://www.govinfo.gov/link/fr/38/9906","by":{"0":"31"}},{"t":"reg","label":"72 Fed. Reg. 73,708","url":"https://www.govinfo.gov/link/fr/72/73708","by":{"0":"31, 32"}},{"t":"reg","label":"83 Fed. Reg. 29,312","url":"https://www.govinfo.gov/link/fr/83/29312","by":{"0":"37"}},{"t":"reg","label":"84 Fed. Reg. 50","url":"https://www.govinfo.gov/link/fr/84/50","by":{"0":"44"}},{"t":"reg","label":"85 Fed. Reg. 13,186","url":"https://www.govinfo.gov/link/fr/85/13186","by":{"0":"31"}}]};